using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalStructureAlignment{static HospitalStructureAlignment(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalStructureAlignment.request"))return;File.Delete("HospitalStructureAlignment.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalStructureAlignment.txt",e.ToString());Debug.LogException(e);}}static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var source=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(g=>g.name=="Building_06_01_Material #26_0");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeHospitalStructureAlignment");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeHospitalStructureAlignment/Scene.unity",true);int walls=0,cladding=0,frontProtected=0;foreach(var f in source.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;File.Copy(AssetDatabase.GetAssetPath(mesh),"FinalEnvironmentRoadBackup/BeforeHospitalStructureAlignment/"+Path.GetFileName(AssetDatabase.GetAssetPath(mesh)),true);var ps=mesh.vertices;var ids=mesh.triangles;var normals=mesh.normals;var old=mesh.uv;var pp=new List<Vector3>();var nn=new List<Vector3>();var uv=new List<Vector2>();var ii=new List<int>();var cache=new Dictionary<long,int>();var lightUV=new List<Vector2>();var sourceLight=mesh.uv2;for(int k=0;k<ids.Length;k+=3){var a=f.transform.TransformPoint(ps[ids[k]]);var b=f.transform.TransformPoint(ps[ids[k+1]]);var c=f.transform.TransformPoint(ps[ids[k+2]]);var n=Vector3.Cross(b-a,c-a).normalized;var center=(a+b+c)/3;bool front=n.x>.65f&&center.x>-140;bool upper=center.y>46;bool distant=f.gameObject!=source.gameObject;bool rear=n.x<-.65f;bool side=Mathf.Abs(n.z)>.65f;bool glass=false;if(rear)glass=distant||Mathf.Abs(center.x-(upper?-193.79f:-199.71f))<.38f;else if(side){float first=upper?-302.73f:-291.73f,second=upper?-401.06f:-412.06f;glass=distant||Mathf.Min(Mathf.Abs(center.z-first),Mathf.Abs(center.z-second))<.40f;}int category=front?0:Mathf.Abs(n.y)>.65f?1:glass?(upper?3:2):4;if(front)frontProtected++;else if(glass)walls++;else cladding++;foreach(int v in new[]{ids[k],ids[k+1],ids[k+2]}){long key=(long)v*5+category;if(!cache.TryGetValue(key,out int index)){index=pp.Count;cache[key]=index;pp.Add(ps[v]);nn.Add(normals[v]);if(sourceLight.Length==ps.Length)lightUV.Add(sourceLight[v]);var w=f.transform.TransformPoint(ps[v]);Vector2 mapped;if(front)mapped=old[v];else if(category==1)mapped=new Vector2(.02f,.98f);else if(glass){float h;if(rear)h=1-Mathf.InverseLerp(upper?-402.0229f:-414.0647f,upper?-301.7635f:-289.7646f,w.z);else{h=Mathf.InverseLerp(upper?-194.8304f:-200.9192f,upper?-121.321f:-115.2816f,w.x);if(n.z<0)h=1-h;}float floor=(w.y-(upper?45.70f:27.6664f))/(upper?13.77861f:18.0336f);mapped=new Vector2(16+Mathf.Lerp(.145f,.855f,h),floor);}else{ // Recessed service walls, columns and canopies use neutral existing silver-grey facade cladding.
mapped=new Vector2(32f+(w.x+w.z)/1.5f-Mathf.Floor((w.x+w.z)/1.5f),w.y/3f);}
uv.Add(mapped);}ii.Add(index);}}int originalTriangles=ids.Length;mesh.Clear();mesh.indexFormat=pp.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16;mesh.SetVertices(pp);mesh.SetNormals(nn);mesh.SetUVs(0,uv);if(lightUV.Count==pp.Count)mesh.SetUVs(1,lightUV);mesh.SetTriangles(ii,0);mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);if(mesh.triangles.Length!=originalTriangles)throw new Exception("Geometry triangle count changed");}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/HospitalStructureAlignment.txt","SUCCESS: actual wall planes receive continuous world-level window courses, including upper wall overlap below roof line. Recesses, columns, service projections and canopy pieces use neutral cladding rather than stretched window photographs. Accepted front triangles preserved="+frontProtected+" window triangles="+walls+" cladding/roof triangles="+cladding+". Near/far triangle counts unchanged; same atlas/material. Shader errors="+ShaderUtil.ShaderHasError(source.GetComponent<Renderer>().sharedMaterial.shader));File.WriteAllText("HospitalStructureViews.request","run");}}

